import hashlib

class TinyHLL:
    def __init__(self, p=10):
        self.p = p
        self.m = 1 << p
        self.regs = bytearray(self.m)

    def _hash64(self, x: str) -> int:
        # Use a uniform non-crypto hash in prod (e.g. xxhash/murmur).
        # hashlib here is only for readability.
        return int.from_bytes(hashlib.sha256(x.encode()).digest()[:8], "big")

    def add(self, x: str):
        h = self._hash64(x)
        idx = h >> (64 - self.p)          # first p bits: which register
        w = (h << self.p) & ((1 << 64) - 1)  # remaining bits
        # rank = leading zeros in w plus 1, capped to fit a register
        rank = 1
        bit = 1 << 63
        while bit & w == 0 and rank < 64 - self.p:
            rank += 1
            bit >>= 1
        if rank > self.regs[idx]:
            self.regs[idx] = rank

    def merge(self, other: "TinyHLL"):
        assert self.p == other.p, "p must match or merge is garbage"
        for i in range(self.m):
            if other.regs[i] > self.regs[i]:
                self.regs[i] = other.regs[i]

    def count(self) -> float:
        import math
        m = self.m
        inv_sum = sum(2.0 ** -r for r in self.regs)
        alpha = 0.7213 / (1 + 1.079 / m) if m >= 128 else 0.673 if m == 64 else 0.697 if m == 32 else 0.709
        est = alpha * m * m / inv_sum
        zeros = self.regs.count(0)
        if est <= 2.5 * m and zeros:
            est = m * math.log(m / zeros)  # linear counting fallback
        return est
